Method.Source:
    /// <summary>
    ///  Data entity data source runtime context.
    /// </summary>
    /// <param name = "_entityCtx">Data entity runtime context.</param>
    /// <param name = "_dataSourceCtx">Data entity data source runtime context.</param>
      public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        this.skipDataSourceValidateField(fieldNum(METPurchParmLineEntity, ParmId), true);
        this.skipDataSourceValidateField(fieldNum(METPurchParmLineEntity, PurchId), true);
        this.skipDataSourceValidateField(fieldNum(METPurchParmLineEntity, LineNum), true);

        super(_entityCtx, _dataSourceCtx);

        switch (_entityCtx.getDatabaseOperation())
        {
            case DataEntityDatabaseOperation::Insert:
                switch (_dataSourceCtx.name())
                {
                    case dataEntityDataSourceStr(METPurchParmLineEntity, PurchParmLine):
                        this.mapPurchParmLine(_dataSourceCtx);
                        break;
                }
                break;
        }
    }

    /// <summary>
    /// Validates purchLine.
    /// </summary>
    /// <param name = "_purchLine">
    /// <c>PurchLine</c>
    /// </param>
    /// <returns>Container containing valid check and error message.</returns>
    private container validatePurchLine(PurchLine _purchLine)
    {
        if (_purchLine.PurchStatus == PurchStatus::Received)
        {
            return [false, "@MET:POLineReceived"];
        }

        return [true, ''];
    }

    /// <summary>
    /// Validates <c>PurchParmTable</c>.
    /// It checks if <c>PurchParmTable</c> record exists against the ParmId.
    /// It also checks if the record is created with MetIsIntegration check.
    /// </summary>
    /// <returns>Valid, if true; otherwise, false.</returns>
    private boolean validatePurchParmTable()
    {
        PurchParmTable purchParmTable;

        return 
            (select firstonly RecId from purchParmTable
                    where purchParmTable.ParmId == this.ParmId
                    &&    purchParmTable.TableRefId == this.ParmId
                    &&    purchParmTable.METIsIntegration == NoYes::Yes).RecId != 0;
    }

    /// <summary>
    /// Maps entity to <c>PurchParmLine</c> datasource.
    /// </summary>
    /// <param name = "_dataSourceCtx">
    /// <c>DataEntityDataSourceRuntimeContext</c>.
    /// </param>
    private void mapPurchParmLine(DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        PurchParmTable purchParmTable;
        PurchParmLine  purchParmLine;
        PurchLine      purchLine;
        boolean        isValid;
        str            errorMessage;

        purchParmLine = _dataSourceCtx.getBuffer();
        purchLine = PurchLine::find(this.PurchId, this.LineNum);

        [isValid, errorMessage] = this.validatePurchLine(purchLine);

        if (!isValid)
        {
            throw error(errorMessage);
        }
                
        purchParmLine.initFromPurchLine(purchLine);

        purchParmLine.PdsCWReceiveNow = this.CWUpdate;
        purchParmLine.ReceiveNow = this.Qty;
        purchParmLine.PdsCWPreviousReceiveNow = this.CWQty;

        purchParmLine.setQty(DocumentStatus::PackingSlip, false, true);
        purchParmLine.setLineAmount();

        purchParmLine.InventDimId = purchLine.InventDimId;
        purchParmLine.TableRefId = purchParmLine.ParmId;

        _dataSourceCtx.setBuffer(purchParmLine);
    }

    /// <summary>
    /// Validates entity.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (ret && !this.validatePurchParmTable())
        {
            ret = checkFailed(strFmt("@MET:PurchParmNotFound", this.ParmId));
        }
    
        return ret;
    }

    /// <summary>
    /// Runs when process finishes
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">
    /// DMF group execution definition.
    /// </param>
    public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        METPurchParmLineStaging parmStaging;
        PurchParmTable          parmTable;
            
        // Update if processing of all records are not completed
        update_recordset parmTable
            setting METIntegrationStatus = METIntegrationStatus::Error
        exists join parmStaging
            where parmStaging.ParmId          == parmTable.ParmId
            && parmStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && parmStaging.ExecutionId     == _dmfDefinitionGroupExecution.ExecutionId
            && parmStaging.TransferStatus  != DMFTransferStatus::Completed;

        // Update if processing of all records are completed
        update_recordset parmTable
                setting METIntegrationStatus = METIntegrationStatus::ReadyToProcess
            where parmTable.METIntegrationStatus == METIntegrationStatus::None
        exists join parmStaging
            where parmStaging.ParmId       == parmTable.ParmId
            && parmStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && parmStaging.ExecutionId     == _dmfDefinitionGroupExecution.ExecutionId;
    }
